var urls = ['https://accounts.google.com', 'https://www.google.com', 'https://chrome.google.com/webstore']; 
 var options = { 
   url: urls[0], 
   method: 'GET', 
 }; 

 var request = require('request'); 

 urls.forEach(function(url) { 
   options.url = url; 
   request(options, function(error, response, body) { 
     if (error) { 
       console.error('Request error:', error); 
     } else { 
       console.log('Request to ' + url + ' completed with status code:', response && response.statusCode); 
     } 
   }); 
));

